package com.xiaoyang.screenmarker;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;

public class OverlayService extends Service {
 WindowManager wm; FrameLayout root; Board board; int color=Color.RED; int tool=0; boolean hidden=false; int[] colors={Color.RED,Color.YELLOW,Color.CYAN,Color.WHITE}; int ci=0; WindowManager.LayoutParams lp;
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);root=new FrameLayout(this);root.setBackgroundColor(Color.TRANSPARENT); board=new Board();root.addView(board,new FrameLayout.LayoutParams(-1,-1)); LinearLayout bar=new LinearLayout(this);bar.setBackgroundColor(0xdd222222); String[] names={"笔","箭头","圆","框","擦","色","清","—"}; for(int n=0;n<names.length;n++){final int k=n;Button b=new Button(this);b.setText(names[n]);b.setTextSize(12);bar.addView(b,new LinearLayout.LayoutParams(0,72,1));b.setOnClickListener(v->{if(k<5){tool=k;board.invalidate();}else if(k==5){ci=(ci+1)%colors.length;color=colors[ci];}else if(k==6){board.paths.clear();board.invalidate();}else{hidden=!hidden;bar.setVisibility(hidden?View.GONE:View.VISIBLE);}});}root.addView(bar);lp=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);wm.addView(root,lp); }
 public void onDestroy(){if(root!=null)wm.removeView(root);super.onDestroy();}
 class Board extends View { java.util.ArrayList<Shape> paths=new java.util.ArrayList<>(); Shape cur; Paint p=new Paint(3); Board(){super(OverlayService.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);} protected void onDraw(Canvas c){for(Shape s:paths)draw(c,s);if(cur!=null)draw(c,cur);} void draw(Canvas c,Shape s){p.setColor(s.color);p.setStrokeWidth(s.tool==4?36:7);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND); if(s.tool==0||s.tool==4){for(int i=1;i<s.pts.size();i++)c.drawLine(s.pts.get(i-1).x,s.pts.get(i-1).y,s.pts.get(i).x,s.pts.get(i).y,p);}else if(s.tool==2)c.drawOval(Math.min(s.x,s.ex),Math.min(s.y,s.ey),Math.max(s.x,s.ex),Math.max(s.y,s.ey),p);else if(s.tool==3)c.drawRect(Math.min(s.x,s.ex),Math.min(s.y,s.ey),Math.max(s.x,s.ex),Math.max(s.y,s.ey),p);else if(s.tool==1){c.drawLine(s.x,s.y,s.ex,s.ey,p);float a=(float)Math.atan2(s.ey-s.y,s.ex-s.x);for(int d=-1;d<=1;d+=2)c.drawLine(s.ex,s.ey,s.ex-34*(float)Math.cos(a+d*.55f),s.ey-34*(float)Math.sin(a+d*.55f),p);}} public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getRawX(),y=e.getRawY();if(e.getAction()==0){cur=new Shape(tool,color,x,y);cur.pts.add(new PointF(x,y));invalidate();return true;}if(e.getAction()==1||e.getAction()==2){cur.ex=x;cur.ey=y;if(tool==0||tool==4)cur.pts.add(new PointF(x,y));if(e.getAction()==1){paths.add(cur);cur=null;}invalidate();return true;}return true;} }
 class Shape{int tool,color;float x,y,ex,ey;java.util.ArrayList<PointF> pts=new java.util.ArrayList<>();Shape(int t,int c,float a,float b){tool=t;color=c;x=ex=a;y=ey=b;}}
}
